<script setup>
import { inject, reactive, ref, watch } from 'vue';
import { api } from '../../api';
import { t } from '../../i18n';
defineProps({ active: Boolean });
const { settings, perform, refresh } = inject('settings');
const defaults = () => ({ id: '', display: '', provider: settings.providers[0]?.id || '', model_name: '', base_url: '', max_rounds: 50, max_tokens: 4096, cost_in: 0, cost_out: 0 });
const form = reactive(defaults());
const discoveryProvider = ref(settings.providers[0]?.id || ''), discovered = ref([]), status = ref(''), discoveryStatus = ref('');
watch(() => settings.providers, providers => { if (!providers.some(p => p.id === discoveryProvider.value)) discoveryProvider.value = providers[0]?.id || ''; if (!providers.some(p => p.id === form.provider)) form.provider = providers[0]?.id || ''; }, { immediate: true });
async function toggle(m, enabled) { await refresh(await api(`/api/settings/models/${encodeURIComponent(m.id)}/toggle`, { enabled })); }
async function remove(m) { await refresh(await api(`/api/settings/models/${encodeURIComponent(m.id)}`, undefined, 'DELETE')); }
function edit(m) { Object.assign(form, defaults(), m, { cost_in: m.cost_per_m?.[0] || 0, cost_out: m.cost_per_m?.[1] || 0 }); status.value = t('Editing “{n}”.', { n: m.display }); }
async function save() { if (!form.id.trim() || !form.model_name.trim()) { status.value = t('Id and API model name are both required.'); return; } await refresh(await api('/api/settings/models', { ...form, id: form.id.trim(), model_name: form.model_name.trim() })); status.value = t('Saved “{n}”.', { n: form.display || form.id }); }
async function discover() { discoveryStatus.value = t('Asking the provider…'); const result = await api(`/api/settings/providers/${encodeURIComponent(discoveryProvider.value)}/available`); discovered.value = result.models || []; discoveryStatus.value = t('{n} chat model(s)', { n: discovered.value.length }); }
async function add(m) { await refresh(await api('/api/settings/models', { id: m.id, display: m.id, provider: discoveryProvider.value, model_name: m.id, max_rounds: 50, max_tokens: 4096 })); await discover(); }
const fields = [['id', 'maId', 'Id'], ['display', 'maDisplay', 'Display name'], ['model_name', 'maModelName', 'API model name'], ['base_url', 'maBaseUrl', 'Base URL'], ['max_rounds', 'maRounds', 'Max rounds', 'number'], ['max_tokens', 'maTokens', 'Max tokens', 'number'], ['cost_in', 'maCostIn', 'Input cost per 1M', 'number'], ['cost_out', 'maCostOut', 'Output cost per 1M', 'number']];
</script>
<template>
  <div id="paneModels" class="set-pane" :class="{ hidden: !active }"><div id="modelList" class="model-list"><div v-for="m in settings.models" :key="m.id" class="model-row" :class="{ 'not-ready': !m.ready }"><input type="checkbox" :checked="m.enabled" @change="perform(() => toggle(m, $event.target.checked))" /><span class="model-name">{{ m.display }}</span><span class="model-meta">{{ m.provider_display }} · {{ m.model_name }}</span><span class="model-spacer"></span><span class="model-flag">{{ t(m.ready ? 'ready' : m.blocked || 'no key') }}</span><button class="mini-btn md-edit" @click="edit(m)">{{ t('Edit') }}</button><button class="mini-btn danger md-del" @click="perform(() => remove(m))">{{ t(m.custom ? 'Delete' : 'Disable') }}</button></div></div><div class="model-discover"><div class="ma-title">{{ t('What your providers are serving right now') }}</div><div class="disc-bar"><select id="discProvider" v-model="discoveryProvider" class="model-select"><option v-for="p in settings.providers" :key="p.id" :value="p.id">{{ p.display }}</option></select><button id="discFetch" class="mini-btn primary" @click="perform(discover)">{{ t('Fetch model list') }}</button><span id="discStatus" class="tf-status">{{ discoveryStatus }}</span></div><div id="discList" class="disc-list"><span v-for="m in discovered" :key="m.id" class="disc-item" :class="{ added: m.already_added }">{{ m.id }}<span v-if="m.already_added" class="model-flag">{{ t('added') }}</span><button v-else class="disc-add" @click="perform(() => add(m))">＋</button></span></div></div><div id="modelAdd" class="model-add"><div class="ma-title">{{ t('Add / edit a model') }}</div><div class="ma-grid"><label v-for="[key, id, label, type] in fields" :key="key"><span>{{ t(label) }}</span><input v-if="type === 'number'" :id="id" v-model.number="form[key]" class="text-input" type="number" step="any" /><input v-else :id="id" v-model="form[key]" class="text-input" /></label><label><span>{{ t('Provider') }}</span><select id="maProvider" v-model="form.provider" class="model-select"><option v-for="p in settings.providers" :key="p.id" :value="p.id">{{ p.display }}</option></select></label></div><div class="ma-actions"><span id="maStatus" class="tf-status">{{ status }}</span><span class="ca-spacer"></span><button id="maReset" class="reset-btn" @click="Object.assign(form, defaults()); status = ''">{{ t('Clear form') }}</button><button id="maSave" class="primary-btn" @click="perform(save)">{{ t('Save model') }}</button></div></div></div>
</template>
